#include <iostream>

int main() {
    int num1 = 0;
    int num2 = 0;

    if (std::cin >> num1 >> num2) {
        if (num1 == num2) {
            std::cout << num1 << " == " << num2 << "\n";
        }
        if (num1 != num2) {
            std::cout << num1 << " != " << num2 << "\n";
        }
        if (num1 < num2) {
            std::cout << num1 << " < " << num2 << "\n";
        }
        if (num1 > num2) {
            std::cout << num1 << " > " << num2 << "\n";
        }
        if (num1 <= num2) {
            std::cout << num1 << " <= " << num2 << "\n";
        }
        if (num1 >= num2) {
            std::cout << num1 << " >= " << num2 << "\n";
        }
    }

    return 0;
}
